package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {





    @Test
    public void testCreateNumber_HexInteger() {
        // Test various hex prefixes and integer/long/biginteger logic
        assertTrue(NumberUtils.createNumber("0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("0X123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0X123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("#123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-#123") instanceof Integer);

        // Leading zeros in hex
        assertTrue(NumberUtils.createNumber("0x000123") instanceof Integer);

        // Long range hex (8 digits or more)
        assertTrue(NumberUtils.createNumber("0x7FFFFFFF") instanceof Long); 
        assertTrue(NumberUtils.createNumber("0x80000000") instanceof Long);

        // BigInteger range hex (> 16 digits)
        assertTrue(NumberUtils.createNumber("0x1234567890ABCDEF1") instanceof BigInteger);
    }


















}

