package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {









    @Test
    public void testCreateNumber_DecimalAndExponent() {
        // Float logic (<= 7 decimals)
        assertTrue(NumberUtils.createNumber("1.234567") instanceof Float);
        // Double logic (8-16 decimals)
        assertTrue(NumberUtils.createNumber("1.234567890123456") instanceof Double);
        // BigDecimal logic (> 16 decimals)
        assertTrue(NumberUtils.createNumber("1.234567890123456789") instanceof BigDecimal);

        // Exponent logic
        assertTrue(NumberUtils.createNumber("1e2") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.2e2") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.23456789e2") instanceof Double);
    }














}

package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {











    @Test
    public void testCreateNumber_Suffixes() {
        // Long suffix
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);
        assertTrue(NumberUtils.createNumber("-123L") instanceof Long);
        // BigInteger via Long suffix overflow
        assertTrue(NumberUtils.createNumber("9223372036854775808L") instanceof BigInteger);

        // Float suffix
        assertTrue(NumberUtils.createNumber("123.45f") instanceof Float);
        assertTrue(NumberUtils.createNumber("123.45F") instanceof Float);

        // Double suffix
        assertTrue(NumberUtils.createNumber("123.45d") instanceof Double);
        assertTrue(NumberUtils.createNumber("123.45D") instanceof Double);

        // Fallthrough to BigDecimal
        assertTrue(NumberUtils.createNumber("123.45x") instanceof BigDecimal); // This will actually throw NFE in the switch default
    }












}

